// Minimal synthetic replica of recyclerlistview's pure-JS surface.
export class DataProvider {
  constructor(rowHasChanged) {
    this.rowHasChanged = rowHasChanged;
    this._data = [];
  }
  cloneWithRows(data) {
    const clone = new DataProvider(this.rowHasChanged);
    clone._data = data;
    return clone;
  }
  getSize() {
    return this._data.length;
  }
}
export class LayoutProvider {
  constructor(getLayoutType, setLayout) {
    this.getLayoutType = getLayoutType;
    this.setLayout = setLayout;
  }
}
export const RECYCLERLISTVIEW_OK = "RECYCLERLISTVIEW_OK";
